def flood_fill_component(grid, start_r, start_c):
    """Find all pixels in the same connected component"""
    color = grid[start_r][start_c]
    visited = set()
    stack = [(start_r, start_c)]
    while stack:
        r, c = stack.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    stack.append((nr, nc))
    return visited

