def fill_holes(grid):
    """Fill holes - zeros completely surrounded by non-zeros"""
    rows, cols = len(grid), len(grid[0])

    # First, find all background pixels reachable from edges
    bg_reachable = [[False]*cols for _ in range(rows)]
    queue = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0]

    # Start BFS from boundary cells
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                if grid[r][c] == 0:
                    bg_reachable[r][c] = True

    changed = True
    while changed:
        changed = False
        new_queue = []
        for r, c in queue:
            if bg_reachable[r][c]:
                continue
            bg_reachable[r][c] = True
            changed = True
            new_queue.append((r, c))

        for nr, nc in set(new_queue):
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                rr, cc = nr + dr, nc + dc
                if 0 <= rr < rows and 0 <= cc < cols:
                    if not bg_reachable[rr][cc] and grid[rr][cc] == 0:
                        if (rr, cc) not in queue:
                            queue.append((rr, cc))

    # Actually let me use a simpler approach - just flood fill all connected background
    # starting from boundary, then remaining background pixels are holes

    visited = [[False]*cols for _ in range(rows)]
    queue = deque([(r,c) for r in range(rows) for c in range(cols) 
                   if grid[r][c] == 0 and (r==0 or r==rows-1 or c==0 or c==cols-1)])

    while queue:
        r, c = queue.popleft()
        if visited[r][c]:
            continue
        visited[r][c] = True
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and not visited[nr][nc]:
                queue.append((nr, nc))

    # Fill unvisited zeros (they're holes!)
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                # Find what color surrounds this hole - take majority of neighbors
                neighbor_colors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbor_colors.append(grid[nr][nc])
                if neighbor_colors:
                    from collections import Counter
                    most_common = Counter(neighbor_colors).most_common(1)[0][0]
                    result[r][c] = most_common
                else:
                    result[r][c] = 9  # Default fill if unknown

    return result

