def find_colors_with_holes(grid):
    """For each color, determine if it has any enclosed holes"""
    rows, cols = len(grid), len(grid[0])

    # BFS from all boundary zeros to mark reachable background
    reachable_bg = [[False]*cols for _ in range(rows)]
    queue = deque()

    # Add all boundary zeros to queue
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1) and grid[r][c] == 0:
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        if reachable_bg[r][c]:
            continue
        reachable_bg[r][c] = True

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not reachable_bg[nr][nc] and grid[nr][nc] == 0:
                    queue.append((nr, nc))

    # Zeros not reachable are enclosed holes
    colors_with_holes = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                color = grid[r][c]
                if not reachable_bg[r][c]:  # There's a zero behind this pixel
                    # Actually we need to check if THIS pixel has a zero hole behind it
                    # Check neighbors for unreached zeros
                    has_unreachable_zero = False
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 0 and not reachable_bg[nr][nc]:
                                has_unreachable_zero = True
                                break
                    if has_unreachable_zero:
                        colors_with_holes.add(color)

    return sorted(colors_with_holes)

